<script>
const form=document.getElementById('homepage-form');const csrf=<?=json_encode($csrf,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const statusNode=document.getElementById('status');const imageKeys=["logo","hero1","hero2","hero3","hero4","introFeatureImage","partnerFeature","partnerGuide","partnerLodging","partnerCrafts"];
async function api(method='GET',data=null){const response=await fetch('../api/homepage-settings.php',{method,credentials:'same-origin',headers:{Accept:'application/json',...(data?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{})},body:data?JSON.stringify(data):undefined});const payload=await response.json();if(!response.ok)throw new Error(payload.error?.message||'Une erreur est survenue.');return payload;}
async function uploadImage(slot,file){const node=document.querySelector('[data-image-status="'+slot+'"]');node.textContent='Téléversement…';const body=new FormData();body.append('slot',slot);body.append('image',file);try{const response=await fetch('../api/page-content-image.php',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-Token':csrf},body});const payload=await response.json();if(!response.ok)throw new Error(payload.error?.message||'Échec du téléversement.');form.elements[slot].value=payload.data.path;document.querySelector('[data-preview="'+slot+'"]').src=payload.data.path;node.textContent='Image chargée — enregistrez pour publier le changement.';}catch(error){node.textContent=error.message;}}
document.querySelectorAll('[data-upload]').forEach(input=>input.addEventListener('change',()=>{const file=input.files?.[0];if(file)uploadImage(input.dataset.upload,file);}));
(async()=>{try{const payload=await api();for(const [key,value] of Object.entries(payload.data||{})){if(form.elements[key]&&form.elements[key].type!=='file')form.elements[key].value=value;}for(const slot of imageKeys){const path=payload.data?.[slot]||'';const preview=document.querySelector('[data-preview="'+slot+'"]');if(preview)preview.src=path;}statusNode.textContent='Contenu chargé.';}catch(error){statusNode.textContent=error.message;}})();
form.addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('save');button.disabled=true;statusNode.textContent='Enregistrement…';const data=Object.fromEntries([...form.querySelectorAll('[name]')].filter(el=>el.type!=='file').map(el=>[el.name,el.value]));try{await api('PUT',data);statusNode.textContent='Modifications enregistrées. Actualisez le site public pour les voir.';}catch(error){statusNode.textContent=error.message;}finally{button.disabled=false;}});
</script></body></html>